  7	
  8	// Question 1
  9	method Tangent(r: array<int>, x: array<int>)
 10	  returns (found: bool)
 11	  requires forall i:: 1 <= i < x.Length ==> 
 12	           x[i-1] < x[i]
 13	  requires forall i, j ::
 14	           0 <= i < j < x.Length ==>
 15	           x[i] < x[j]
 16	  ensures !found ==>
 17	          forall i,j ::
 18	          0 <= i < r.Length &&
 19	          0 <= j < x.Length ==>
 20	          r[i] != x[j]
 21	  ensures found ==>
 22	          exists i,j ::
 23	          0 <= i < r.Length &&
 24	          0 <= j < x.Length &&
 25	          r[i] == x[j]
 26	{
 27	  found := false;
 28	  var n, f := 0, x.Length;
 29	
 30	  while n != r.Length && !found
 31	    invariant 0 <= n <= r.Length
 32	    invariant !found ==>
 33	              forall i,j ::
 34	              0 <= i < n &&
 35	              0 <= j < x.Length ==>
 36	              r[i] != x[j]
 37	    invariant found ==>
 38	              exists i,j ::
 39	              0 <= i < r.Length &&
 40	              0 <= j < x.Length &&
 41	              n == i && f == j &&
 42	              r[i] == x[j]
 43	    decreases r.Length - n, !found
 44	  {
 45	    f := BinarySearch(x, r[n]);
 46	    /*
 47	    not iterate over either array
 48	    once a tangent has been found
 49	    */ // see if
 50	    if (f != x.Length && r[n] == x[f]) {
 51	      found := true;
 52	    } else {
 53	      n := n + 1;
 54	    }
 55	  }
 56	
 57	  assert
 58	    (!found && n == r.Length) ||
 59	    ( found && n != r.Length && r[n] == x[f]);
 60	  assert
 61	    !false; // sanity check
 62	}
 63	
 64	// Author: Leino, Title: Program Proofs
 65	method BinarySearch(a: array<int>, circle: int)
 66	  returns (n: int)
 67	  requires forall i ::
 68	           1 <= i < a.Length
 69	           ==> a[i-1] < a[i]
 70	  requires forall i, j ::
 71	           0 <= i < j < a.Length ==>
 72	           a[i] < a[j]
 73	  ensures 0 <= n <= (a.Length) - 1
 74	  ensures forall i ::
 75	          0 <= i < n ==>
 76	          a[i] < circle
 77	  ensures forall i ::
 78	          n <= i < a.Length ==>
 79	          circle <= a[i]
 80	{
 81	  var lo, hi := 0, a.Length;
 82	
 83	  while lo < hi
 84	    invariant 0 <= lo <= hi <= a.Length
 85	    invariant forall i ::
 86	              0 <= i < lo ==>
 87	              a[i] < circle
 88	    invariant forall i ::
 89	              hi <= i < a.Length ==>
 90	              a[i] >= circle
 91	    decreases hi - lo
 92	  {
 93	    var mid := (lo + hi) / 2;
 94	    calc {
 95	      lo;
 96	    ==
 97	      (lo + lo) / 2;
 98	    <= { assert lo <= hi; }
 99	      (lo + hi) / 2;
100	    < { assert lo < hi; }
101	      (hi + hi) / 2;
102	    ==
103	      hi;
104	    }
105	    /*
106	      for a given circle in r,
107	      should not iterate over array x
108	      once it can be deduced that
109	      no tangent will be found for that circle.
110	      */ // see if and 1st else if
111	    if (a[lo] > circle) {
112	      hi := lo;
113	    } else if (a[hi-1] < circle) {
114	      lo := hi;
115	    } else if (a[mid] < circle) {
116	      lo := mid + 1;
117	    } else {
118	      hi := mid;
119	    }
120	  }
121	
122	  n := lo;
123	  assert
124	    !false; // sanity check
125	}
